      &lt;/div&gt;
    &lt;/div&gt;

    &lt;!-- Realistic Tonearm Assembly on Right Side of the Deck --&gt;
    &lt;div class="tonearm-column"&gt;
      &lt;div class="tonearm-base"&gt;
        &lt;div class="tonearm-counterweight"&gt;&lt;/div&gt;
      &lt;/div&gt;

      &lt;div class="tonearm-rod" style="${isSpinning ? '' : 'transform: rotate(-18deg); animation: none;'}"&gt;
        &lt;div class="tonearm-headshell"&gt;
          &lt;div class="needle-light"&gt;&lt;/div&gt;
        &lt;/div&gt;
      &lt;/div&gt;

      &lt;div class="pitch-control"&gt;
