  &lt;/div&gt;

  &lt;!-- Bottom Console: Illuminated LCD Monitor Screen & Deck Controls --&gt;
  &lt;div class="turntable-lcd-screen"&gt;
    &lt;div class="lcd-playback-line"&gt;
      &lt;div&gt;
        &lt;div style="font-size: 0.7rem; color: #00f2fe; font-family: monospace; letter-spacing: 1.5px; font-weight: 700;"&gt;
          ⚡ NEEDLE DROP // ACTIVE GROOVE
        &lt;/div&gt;
        &lt;div class="lcd-album-title"&gt;
          ${spotlight.album}
        &lt;/div&gt;
        &lt;div style="font-size: 0.95rem; color: #cbd5e1; font-family: monospace;"&gt;
          ${spotlight.artist} &lt;span style="color: #ffd166;"&gt;(${spotlight.year})&lt;/span&gt;
        &lt;/div&gt;
      &lt;/div&gt;

      &lt;!-- Equalizer Visualizer Bars --&gt;
      &lt;div class="equalizer-wrap" style="height: 22px; margin: 0;"&gt;
        &lt;div class="eq-bar" style="${isSpinning ? '' : 'animation: none; height: 30%;'}"&gt;&lt;/div&gt;
        &lt;div class="eq-bar" style="${isSpinning ? '' : 'animation: none; height: 30%;'}"&gt;&lt;/div&gt;
        &lt;div class="eq-bar" style="${isSpinning ? '' : 'animation: none; height: 30%;'}"&gt;&lt;/div&gt;
        &lt;div class="eq-bar" style="${isSpinning ? '' : 'animation: none; height: 30%;'}"&gt;&lt;/div&gt;
        &lt;div class="eq-bar" style="${isSpinning ? '' : 'animation: none; height: 30%;'}"&gt;&lt;/div&gt;
        &lt;div class="eq-bar" style="${isSpinning ? '' : 'animation: none; height: 30%;'}"&gt;&lt;/div&gt;
        &lt;div class="eq-bar" style="${isSpinning ? '' : 'animation: none; height: 30%;'}"&gt;&lt;/div&gt;
        &lt;div class="eq-bar" style="${isSpinning ? '' : 'animation: none; height: 30%;'}"&gt;&lt;/div&gt;
      &lt;/div&gt;
    &lt;/div&gt;

    &lt;!-- Metadata Chips --&gt;
    &lt;div class="lcd-meta-chips"&gt;
      &lt;span class="lcd-chip" style="color: #ffd166; border-color: rgba(255, 209, 102, 0.4);"&gt;
        ALL-TIME RANK: #${spotlight.rank} OF 1000
      &lt;/span&gt;
      &lt;span class="lcd-chip"&gt;
        RATING: ⭐ ${spotlight.rating ? spotlight.rating.toFixed(2) : "4.00"}
      &lt;/span&gt;
      &lt;span class="lcd-chip" style="text-transform: uppercase;"&gt;
        GENRE: ${spotlight.primary_genre}
      &lt;/span&gt;
      &lt;span class="lcd-chip" style="color: #38ef7d; border-color: rgba(56, 239, 125, 0.4);"&gt;
        GROOVES LIT: ${matchingSet.size} / 1000
      &lt;/span&gt;
    &lt;/div&gt;

    &lt;!-- Turntable Action Buttons --&gt;
    &lt;div class="deck-controls" style="margin-top: 1rem;"&gt;
      &lt;button 
        class="btn-neon" 
        style="background: ${isSpinning ? 'linear-gradient(135deg, #ffd166, #ff7b00)' : 'linear-gradient(135deg, #00f2fe, #4facfe)'}; font-size: 0.85rem; padding: 0.45rem 1.1rem;"
        onclick=${() =&gt; {
          mutable isSpinning = !isSpinning;
        }}
      &gt;
        ${isSpinning ? '⏹ PAUSE PLATTER' : '▶ SPIN PLATTER'}
      &lt;/button&gt;

      &lt;button 
        class="btn-neon" 
        style="font-size: 0.85rem; padding: 0.45rem 1.1rem;"
        onclick=${() =&gt; {
          const randIndex = Math.floor(Math.random() * cleanData.length);
          mutable activeAlbum = cleanData[randIndex];
        }}
