// Main Game Arena Component
html`
&lt;div class="game-arena text-center"&gt;
  &lt;div style="display: flex; justify-content: center; gap: 1.5rem; flex-wrap: wrap;"&gt;
    &lt;div class="streak-counter"&gt;
      🔥 Current Streak: &lt;span style="font-size: 1.25rem;"&gt;${currentStreak}&lt;/span&gt;
    &lt;/div&gt;
    &lt;div class="streak-counter" style="background: rgba(0, 242, 254, 0.15); border-color: rgba(0, 242, 254, 0.35); color: #00f2fe;"&gt;
      🏆 Best Streak: &lt;span style="font-size: 1.25rem;"&gt;${bestStreak}&lt;/span&gt;
    &lt;/div&gt;
  &lt;/div&gt;

  &lt;div class="compare-grid" style="margin: 1.5rem 0;"&gt;
    &lt;!-- Album A (Known) --&gt;
    &lt;div class="compare-box"&gt;
      &lt;div style="font-size: 0.75rem; letter-spacing: 1.5px; color: #00f2fe; text-transform: uppercase; font-weight: 700; margin-bottom: 0.5rem;"&gt;
        BENCHMARK ALBUM
      &lt;/div&gt;
      &lt;img 
        class="compare-cover" 
        src="${gameAlbumA.image_url}" 
        alt="${gameAlbumA.album}" 
        referrerpolicy="no-referrer"
        crossorigin="anonymous"
        onerror="this.src='https://placehold.co/300x300/181b26/00f2fe?text=Album'"
      /&gt;
      &lt;h3 style="color: #fff; font-size: 1.35rem; margin: 0.25rem 0; font-weight: 800;"&gt;${gameAlbumA.album}&lt;/h3&gt;
      &lt;div style="color: #cbd5e1; font-size: 0.95rem; margin-bottom: 0.5rem;"&gt;${gameAlbumA.artist} (${gameAlbumA.year})&lt;/div&gt;
      &lt;div style="font-size: 1.1rem; font-weight: 900; color: #00f2fe; margin-top: 0.5rem;"&gt;
        RANK #${gameAlbumA.rank}
      &lt;/div&gt;
      &lt;div style="font-size: 0.85rem; color: #ffd166;"&gt;⭐ ${gameAlbumA.rating.toFixed(2)}&lt;/div&gt;
    &lt;/div&gt;

    &lt;!-- Center VS Indicator --&gt;
    &lt;div style="text-align: center;"&gt;
      &lt;div class="vs-badge"&gt;VS&lt;/div&gt;
      &lt;div style="font-size: 0.75rem; color: #cbd5e1; margin-top: 0.6rem; font-weight: 600;"&gt;
        Round ${roundCounter}
      &lt;/div&gt;
    &lt;/div&gt;

    &lt;!-- Album B (Mystery) --&gt;
    &lt;div class="compare-box" style="${gameStatus === 'won' ? 'border-color: #00f2fe; box-shadow: 0 0 25px rgba(0, 242, 254, 0.4);' : (gameStatus === 'lost' ? 'border-color: #ff4d4d; box-shadow: 0 0 25px rgba(255, 77, 77, 0.4);' : '')}"&gt;
      &lt;div style="font-size: 0.75rem; letter-spacing: 1.5px; color: #ffd166; text-transform: uppercase; font-weight: 700; margin-bottom: 0.5rem;"&gt;
        MYSTERY ALBUM
      &lt;/div&gt;
      &lt;img 
        class="compare-cover" 
        src="${gameAlbumB.image_url}" 
        alt="${gameAlbumB.album}" 
        referrerpolicy="no-referrer"
        crossorigin="anonymous"
        onerror="this.src='https://placehold.co/300x300/181b26/00f2fe?text=Album'"
      /&gt;
      &lt;h3 style="color: #fff; font-size: 1.35rem; margin: 0.25rem 0; font-weight: 800;"&gt;${gameAlbumB.album}&lt;/h3&gt;
      &lt;div style="color: #cbd5e1; font-size: 0.95rem; margin-bottom: 0.5rem;"&gt;${gameAlbumB.artist} (${gameAlbumB.year})&lt;/div&gt;

      ${gameStatus === 'playing' ? html`
        &lt;div style="font-size: 1.1rem; font-weight: 900; color: #ffd166; margin-top: 0.5rem;"&gt;
          RANK: ❓❓❓
        &lt;/div&gt;
        &lt;div style="font-size: 0.85rem; color: #94a3b8;"&gt;Is it ranked higher or lower?&lt;/div&gt;
      ` : html`
        &lt;div style="font-size: 1.25rem; font-weight: 900; color: ${gameStatus === 'won' ? '#00f2fe' : '#ff4d4d'}; margin-top: 0.5rem;"&gt;
          RANK #${gameAlbumB.rank}
        &lt;/div&gt;
        &lt;div style="font-size: 0.85rem; color: #ffd166;"&gt;⭐ ${gameAlbumB.rating.toFixed(2)}&lt;/div&gt;
      `}
    &lt;/div&gt;
  &lt;/div&gt;

  &lt;!-- Interactive Decision Controls --&gt;
  ${gameStatus === 'playing' ? html`
    &lt;div style="display: flex; justify-content: center; gap: 1rem; flex-wrap: wrap; margin-top: 1rem;"&gt;
      &lt;button class="btn-neon" style="background: linear-gradient(135deg, #00f2fe, #4facfe); font-size: 1rem; padding: 0.65rem 1.6rem;" onclick=${() =&gt; {
        // Higher rank means numerical rank is smaller (e.g. #1 is higher than #10)
        const isHigher = gameAlbumB.rank &lt; gameAlbumA.rank;
        if (isHigher) {
          const newStreak = currentStreak + 1;
          mutable currentStreak = newStreak;
          if (newStreak &gt; bestStreak) mutable bestStreak = newStreak;
          mutable gameStatus = "won";
        } else {
          mutable currentStreak = 0;
          mutable gameStatus = "lost";
        }
      }}&gt;
        ▲ HIGHER RANK (Closer to #1)
      &lt;/button&gt;

      &lt;button class="btn-neon" style="background: linear-gradient(135deg, #ffd166, #ff7b00); font-size: 1rem; padding: 0.65rem 1.6rem;" onclick=${() =&gt; {
        // Lower rank means numerical rank is larger (e.g. #50 is lower than #10)
        const isLower = gameAlbumB.rank &gt; gameAlbumA.rank;
        if (isLower) {
          const newStreak = currentStreak + 1;
          mutable currentStreak = newStreak;
          if (newStreak &gt; bestStreak) mutable bestStreak = newStreak;
          mutable gameStatus = "won";
        } else {
          mutable currentStreak = 0;
          mutable gameStatus = "lost";
        }
      }}&gt;
        ▼ LOWER RANK (Further from #1)
      &lt;/button&gt;
    &lt;/div&gt;
  ` : html`
    &lt;div style="margin-top: 1.25rem;"&gt;
      &lt;div style="font-size: 1.35rem; font-weight: 800; margin-bottom: 1rem; color: ${gameStatus === 'won' ? '#00f2fe' : '#ff4d4d'};"&gt;
        ${gameStatus === 'won' ? '🎉 SPOT ON! You guessed correctly!' : '❌ BUSTED! Better luck next time!'}
      &lt;/div&gt;

      &lt;button class="btn-neon" style="padding: 0.6rem 1.8rem; font-size: 1rem;" onclick=${() =&gt; {
        mutable gameAlbumA = gameAlbumB;
        mutable gameAlbumB = getRandomAlbum(gameAlbumB.rank);
        mutable gameStatus = "playing";
        mutable roundCounter = roundCounter + 1;
      }}&gt;
        ${gameStatus === 'won' ? '🔥 Keep Streak Going →' : '🔄 Play Again'}
      &lt;/button&gt;
    &lt;/div&gt;
  `}
&lt;/div&gt;
`

